// Host test for schedule.h against vectors generated by the Python reference (python -m obc.golden).
// Build & run:  c++ -std=c++17 -Wall -Wextra -Werror -I.. test_schedule.cpp -o /tmp/test_schedule && /tmp/test_schedule schedule.txt
#include "schedule.h"

#include <cmath>
#include <cstdio>
#include <fstream>
#include <sstream>
#include <string>

using namespace openbed::schedule;

int main(int argc, char **argv) {
  std::ifstream in(argc > 1 ? argv[1] : "schedule.txt");
  if (!in.good()) {
    std::fprintf(stderr, "cannot open vectors\n");
    return 1;
  }
  Schedule sch;
  std::string line;
  int checked = 0, failures = 0;
  while (std::getline(in, line)) {
    if (line.empty() || line[0] == '#')
      continue;
    std::istringstream ls(line);
    char kind;
    ls >> kind;
    if (kind == 'P') {
      sch = Schedule{};
      float m, c;
      while (ls >> m >> c)
        sch.add(m, c);
    } else if (kind == 'R') {
      ls >> sch.wake_ramp_min >> sch.wake_target_c;
    } else if (kind == 'S') {
      float minute;
      std::string wake, expected;
      ls >> minute >> wake >> expected;
      float got = sch.setpoint(minute, wake == "-" ? NAN : std::stof(wake));
      bool ok = expected == "off" ? std::isnan(got) : std::fabs(got - std::stof(expected)) < 1e-3f;
      if (!ok) {
        std::fprintf(stderr, "FAIL S %g %s: got %.4f want %s\n", minute, wake.c_str(), got, expected.c_str());
        failures++;
      }
      checked++;
    } else if (kind == 'W') {
      int start, wake, want;
      ls >> start >> wake >> want;
      if (wake_offset_min(start, wake) != want) {
        std::fprintf(stderr, "FAIL W %d %d: got %d want %d\n", start, wake, wake_offset_min(start, wake), want);
        failures++;
      }
      checked++;
    }
  }
  Schedule full;
  for (size_t i = 0; i < MAX_POINTS; i++)
    full.add(i, 20.0f);
  if (full.add(99, 20.0f) || checked < 700)
    failures++;
  if (failures) {
    std::fprintf(stderr, "%d failure(s)\n", failures);
    return 1;
  }
  std::printf("schedule.h: %d vectors OK\n", checked);
  return 0;
}
